 private void configureTable(){colRef.setCellValueFactory(v->new SimpleStringProperty(s(v.getValue().reference())));colDate.setCellValueFactory(v->new SimpleStringProperty(s(v.getValue().invoiceDate())));colSupplier.setCellValueFactory(v->new SimpleStringProperty(s(v.getValue().supplierName())));colInvoice.setCellValueFactory(v->new SimpleStringProperty(s(v.getValue().supplierInvoiceNo())));colValue.setCellValueFactory(v->new SimpleDoubleProperty(v.getValue().invoiceValue()));colLinked.setCellValueFactory(v->new SimpleDoubleProperty(v.getValue().linkedAmount()));colBalance.setCellValueFactory(v->new SimpleDoubleProperty(v.getValue().balance()));colStatus.setCellValueFactory(v->new SimpleStringProperty(s(v.getValue().status())));colSource.setCellValueFactory(v->new SimpleStringProperty(s(v.getValue().source())));for(var c:List.of(colValue,colBalance))c.setCellFactory(x->new TableCell<>(){@Override protected void updateItem(Number n,boolean empty){super.updateItem(n,empty);setText(empty||n==null?null:"₹ "+money(n.doubleValue()));}});colLinked.setCellFactory(x->new TableCell<>(){@Override protected void updateItem(Number n,boolean empty){super.updateItem(n,empty);setText(null);setGraphic(null);setTooltip(null);if(empty||n==null||getIndex()<0||getIndex()>=getTableView().getItems().size())return;var row=getTableView().getItems().get(getIndex());if(n.doubleValue()<=.009||row.bankLinks()==null||row.bankLinks().isEmpty()){setText("—");return;}String label=linkedReferenceLabel(row);Hyperlink link=new Hyperlink(label);link.getStyleClass().add("bank-match-link");link.setGraphic(IconFactory.compactIcon("link",13));link.setOnAction(e->openLinkedAmount(row));link.setTooltip(new Tooltip(linkedReferenceTooltip(row)));setGraphic(link);}});colStatus.setCellFactory(x->SemanticTableCells.status("reconcile"));colAction.setCellFactory(c->new TableCell<>(){private final MenuButton actions=new MenuButton("Actions");private PurchaseReconApiClient.ReconDto row;{actions.getStyleClass().addAll("table-action-menu","approved-row-action");actions.setGraphic(IconFactory.compactIcon("actions",14));actions.setOnShowing(e->rebuild());IconFactory.decorateActionMenu(actions);}private void rebuild(){actions.getItems().clear();if(row==null)return;MenuItem view=new MenuItem("View",IconFactory.compactIcon("view",14));view.setOnAction(e->{table.getSelectionModel().select(row);showDetails(row);});MenuItem edit=new MenuItem("Edit",IconFactory.compactIcon("edit",14));edit.setDisable(!PermissionService.allowed("PURCHASE_RECON.EDIT"));edit.setOnAction(e->editRecord(row));MenuItem del=new MenuItem("Delete",IconFactory.compactIcon("delete",14));del.getStyleClass().add("danger-menu-item");del.setDisable(!PermissionService.allowed("PURCHASE_RECON.DELETE")||row.linkedAmount()>.009);del.setOnAction(e->deleteRecord(row));actions.getItems().add(view);if(row.linkedAmount()>.009){MenuItem bank=new MenuItem(row.bankLinks()!=null&&row.bankLinks().size()>1?"View Bank Statement Links":"Open Bank Statement",IconFactory.compactIcon("bank",14));bank.setOnAction(e->openLinkedAmount(row));actions.getItems().add(bank);}actions.getItems().addAll(edit,del);}@Override protected void updateItem(Void x,boolean empty){super.updateItem(x,empty);row=empty||getIndex()<0||getIndex()>=getTableView().getItems().size()?null:getTableView().getItems().get(getIndex());setGraphic(row==null?null:actions);}});table.setRowFactory(tv->{TableRow<PurchaseReconApiClient.ReconDto> row=new TableRow<>();row.setOnMouseClicked(e->{if(e.getButton()!=javafx.scene.input.MouseButton.PRIMARY||e.getClickCount()!=1||row.isEmpty()||RegisterUiSupport.isInteractiveTableTarget(e.getPickResult().getIntersectedNode(),row))return;var clicked=row.getItem();if(detailDrawer!=null&&detailDrawer.isOpen()&&detailRow==clicked)closeDetails();else{table.getSelectionModel().select(clicked);showDetails(clicked);}e.consume();});return row;});}
