  detailBankLinks=new ListView<>();detailBankLinks.setPrefHeight(120);detailBankLinks.setMaxHeight(150);detailBankLinks.getStyleClass().add("erp-detail-drawer-list");detailBankLinks.setCellFactory(v->new ListCell<>(){@Override protected void updateItem(PurchaseReconApiClient.BankLinkDto b,boolean empty){super.updateItem(b,empty);setText(empty||b==null?null:s(b.bankTransactionDate())+" • "+(s(b.bankReference()).isBlank()?"Bank #"+b.statementTransactionId():b.bankReference())+" • ₹ "+money(b.allocatedAmount())+(s(b.financeVoucherNo()).isBlank()?"":" • "+b.financeVoucherNo()));}});
  detailAttachments=new ListView<>();detailAttachments.setPrefHeight(100);detailAttachments.setMaxHeight(130);detailAttachments.getStyleClass().add("erp-detail-drawer-list");
  detailOpenStatement=new Button("Open Bank Statement");detailOpenStatement.getStyleClass().addAll("approved-button","approved-secondary-button");detailOpenStatement.setGraphic(IconFactory.compactIcon("bank",14));detailOpenStatement.setOnAction(e->openDetailBankStatement());
  detailOpenBankEntry=new Button("Open Bank Entry");detailOpenBankEntry.getStyleClass().addAll("approved-button","approved-secondary-button");detailOpenBankEntry.setGraphic(IconFactory.compactIcon("link",14));detailOpenBankEntry.setOnAction(e->openDetailBankEntry());
  detailPreviewAttachment=new Button("Preview Attachment");detailPreviewAttachment.getStyleClass().addAll("approved-button","approved-secondary-button");detailPreviewAttachment.setGraphic(IconFactory.compactIcon("view",14));detailPreviewAttachment.setOnAction(e->previewDetailAttachment());
  detailBankLinks.getSelectionModel().selectedItemProperty().addListener((o,a,b)->updateDetailButtons());detailAttachments.getSelectionModel().selectedItemProperty().addListener((o,a,b)->updateDetailButtons());
  Label bankTitle=new Label("Bank Statement Links");bankTitle.getStyleClass().addAll("section-title","drawer-section");Label attachmentTitle=new Label("Attachments");attachmentTitle.getStyleClass().addAll("section-title","drawer-section");
  HBox bankButtons=new HBox(7,detailOpenStatement,detailOpenBankEntry);VBox extra=new VBox(8,bankTitle,detailBankLinks,bankButtons,attachmentTitle,detailAttachments,detailPreviewAttachment);detailDrawer.setExtra(extra);
  if(workspaceRow!=null){workspaceRow.getChildren().add(detailDrawer);if(table!=null&&table.getParent()!=null)HBox.setHgrow(table.getParent(),Priority.ALWAYS);OperationalUiSupport.installEscapeClose(workspaceRow,detailDrawer::isOpen,this::closeDetails);}
